#!/usr/bin/env bash
set -euo pipefail

echo "== MEMEFLOW non-custodial Solana LIVE v1 =="
if [[ -f "memeflow-app/package.json" ]]; then APP_DIR="memeflow-app"; elif [[ -f "package.json" && -f "app-server.mjs" ]]; then APP_DIR="."; else echo "ERROR: run from MEMEFLOW repo root or memeflow-app" >&2; exit 1; fi
cd "$APP_DIR"
STAMP="$(date +%Y%m%d-%H%M%S)"; BACKUP_DIR=".live-solana-v1-backup-$STAMP"; mkdir -p "$BACKUP_DIR"
for f in package.json .env.example account-wallet-settings.js memeflow-nav.js settings.html trading.html; do [[ -f "$f" ]] && cp -p "$f" "$BACKUP_DIR/$f"; done
mkdir -p tests
printf '%s' '' | base64 -d > live-bootstrap.mjs
printf '%s' '' | base64 -d > live-wallet-execution.js
printf '%s' '' | base64 -d > tests/live-noncustodial-v1.mjs
printf '%s' '' | base64 -d | python3

echo "Installing Solana transaction library..."
npm install --no-audit --no-fund

echo "Syntax checks..."
node --check live-bootstrap.mjs
node --check live-wallet-execution.js
node --check account-wallet-settings.js

echo "Fail-closed safety test (NO transaction is sent)..."
node tests/live-noncustodial-v1.mjs

echo
echo "INSTALLED. Backup: $PWD/$BACKUP_DIR"
echo "LIVE is still locked until Replit Secrets are set:"
echo "  LIVE_TRADING_ENABLED=true"
echo "  LIVE_SOLANA_RPC_URL=<your HTTPS Solana Mainnet RPC>"
echo "Then restart Replit -> System Settings -> Connect Phantom/Solflare -> Arm LIVE mode."
echo "Every real transaction requires approval in Phantom/Solflare."
